use crate::parts::multi_pattern_match::Matcher;

let iocs = ["evil.example", "198.51.100.7", "/wp-admin/setup.php"];
let matcher = Matcher::new(&iocs)?;

// Every occurrence, overlapping ones included (same as pyahocorasick's Automaton.iter())
for hit in matcher.find_overlapping_iter(&log_line) {
    alert(iocs[hit.pattern], hit.start..hit.end); // byte offsets
}

// Non-overlapping, leftmost-longest
let hits = matcher.find_longest(&payload);

// Just a verdict: stops at the first match
if matcher.is_match(&payload) {
    quarantine();
}
